(function () {
'use strict';
var U = window.U;
var CATEGORIES = [
{ label: '长度', units: [
{ name: '毫米', s: 'mm', f: 0.001 }, { name: '厘米', s: 'cm', f: 0.01 },
{ name: '米', s: 'm', f: 1 }, { name: '千米', s: 'km', f: 1000 },
{ name: '英寸', s: 'in', f: 0.0254 }, { name: '英尺', s: 'ft', f: 0.3048 },
{ name: '码', s: 'yd', f: 0.9144 }, { name: '英里', s: 'mi', f: 1609.344 },
{ name: '海里', s: 'nmi', f: 1852 }] },
{ label: '重量', units: [
{ name: '毫克', s: 'mg', f: 0.000001 }, { name: '克', s: 'g', f: 0.001 },
{ name: '千克', s: 'kg', f: 1 }, { name: '吨', s: 't', f: 1000 },
{ name: '盎司', s: 'oz', f: 0.0283495 }, { name: '磅', s: 'lb', f: 0.453592 },
{ name: '市斤', s: '斤', f: 0.5 }] },
{ label: '面积', units: [
{ name: '平方米', s: 'm²', f: 1 }, { name: '平方厘米', s: 'cm²', f: 0.0001 },
{ name: '平方千米', s: 'km²', f: 1000000 }, { name: '公顷', s: 'ha', f: 10000 },
{ name: '亩', s: 'mu', f: 666.6667 }, { name: '平方英尺', s: 'ft²', f: 0.092903 }] },
{ label: '温度', type: 'temperature', units: [
{ name: '摄氏度', s: '°C' }, { name: '华氏度', s: '°F' }, { name: '开尔文', s: 'K' }] },
{ label: '速度', units: [
{ name: '米/秒', s: 'm/s', f: 1 }, { name: '千米/时', s: 'km/h', f: 0.277778 },
{ name: '英里/时', s: 'mph', f: 0.44704 }, { name: '节', s: 'kn', f: 0.514444 }] },
{ label: '存储', units: [
{ name: '字节', s: 'B', f: 1 }, { name: 'KB', s: 'KB', f: 1024 },
{ name: 'MB', s: 'MB', f: 1048576 }, { name: 'GB', s: 'GB', f: 1073741824 },
{ name: 'TB', s: 'TB', f: 1099511627776 }] },
];
var state = { cat: 0, src: 2, tgt: 3 };
var els = {};
function cat() { return CATEGORIES[state.cat]; }
function unitLabel(u) { return u.name + '（' + u.s + '）'; }
function fmt(n) {
if (!Number.isFinite(n)) return '-';
var abs = Math.abs(n);
if (abs >= 1000000 || (abs > 0 && abs < 0.0001)) {
return n.toExponential(4).replace(/e([+-])(\d+)/, '×10^$1$2');
}
var d = abs >= 100 ? 2 : 4;
return String(parseFloat(n.toFixed(d)));
}
function tempToC(v, idx) {
if (idx === 1) return (v - 32) * 5 / 9;
if (idx === 2) return v - 273.15;
return v;
}
function tempFromC(c, idx) {
if (idx === 1) return c * 9 / 5 + 32;
if (idx === 2) return c + 273.15;
return c;
}
function fillUnits() {
var c = cat();
var html = c.units.map(function (u, i) {
return '<option value="' + i + '">' + unitLabel(u) + '</option>';
}).join('');
els.source.innerHTML = html;
els.target.innerHTML = html;
state.src = Math.min(c.type === 'temperature' ? 0 : 2, c.units.length - 1);
state.tgt = Math.min(state.src + 1, c.units.length - 1);
els.source.value = state.src;
els.target.value = state.tgt;
renderChips();
}
function renderChips() {
var c = cat();
els.chips.innerHTML = c.units.map(function (u, i) {
return '<button type="button" class="chip' + (i === state.tgt ? ' active' : '') + '" data-unit="' + i + '">' + u.s + '</button>';
}).join('');
}
function convert() {
var num = U.numInput(els.value);
if (!Number.isFinite(num)) { els.result.hidden = true; return; }
var c = cat();
var src = c.units[state.src], tgt = c.units[state.tgt];
var out, formula;
if (c.type === 'temperature') {
out = tempFromC(tempToC(num, state.src), state.tgt);
formula = fmt(num) + src.s + ' → ' + fmt(out) + tgt.s + '（经摄氏换算）';
} else {
out = num * src.f / tgt.f;
formula = fmt(num) + ' ' + src.s + ' = ' + fmt(out) + ' ' + tgt.s;
}
els.resultLabel.textContent = '换算结果（' + tgt.s + '）';
els.resultValue.textContent = fmt(out) + ' ' + tgt.s;
els.detail.innerHTML = '<div class="result-detail-row"><dt>输入</dt><dd>' + fmt(num) + ' ' + src.s + '</dd></div>' +
'<div class="result-detail-row"><dt>公式</dt><dd>' + formula + '</dd></div>';
els.result.hidden = false;
}
function onCatChange() {
state.cat = Number(els.category.value);
fillUnits();
convert();
}
function init() {
els.category = document.getElementById('unit-category');
els.source = document.getElementById('unit-source');
els.target = document.getElementById('unit-target');
els.value = document.getElementById('unit-value');
els.chips = document.getElementById('unit-chips');
els.result = document.getElementById('unit-result');
els.resultLabel = document.getElementById('unit-result-label');
els.resultValue = document.getElementById('unit-result-value');
els.detail = document.getElementById('unit-detail');
if (!els.category) return;
els.category.innerHTML = CATEGORIES.map(function (c, i) {
return '<option value="' + i + '">' + c.label + '</option>';
}).join('');
fillUnits();
els.category.addEventListener('change', onCatChange);
els.source.addEventListener('change', function () { state.src = Number(els.source.value); convert(); });
els.target.addEventListener('change', function () { state.tgt = Number(els.target.value); renderChips(); convert(); });
els.value.addEventListener('input', U.debounce(convert, 120));
document.getElementById('unit-swap').addEventListener('click', function () {
var t = state.src; state.src = state.tgt; state.tgt = t;
els.source.value = state.src; els.target.value = state.tgt; renderChips(); convert();
});
els.chips.addEventListener('click', function (e) {
var b = e.target.closest('[data-unit]');
if (!b) return;
state.tgt = Number(b.getAttribute('data-unit'));
els.target.value = state.tgt; renderChips(); convert();
});
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
else init();
})();
